import React, { useState, useCallback, useRef, useEffect, useMemo } from "react";
import {
  View,
  StyleSheet,
  ActivityIndicator,
  Dimensions,
  Platform,
  Linking,
  Pressable,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useHeaderHeight } from "@react-navigation/elements";
import YoutubePlayer, { YoutubeIframeRef } from "react-native-youtube-iframe";
import Animated, {
  FadeIn,
  FadeOut,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  WithSpringConfig,
} from "react-native-reanimated";

import { ThemedText } from "@/components/ThemedText";
import { ThemedView } from "@/components/ThemedView";
import { YouTubePlayerWeb } from "@/components/YouTubePlayerWeb";
import { useTheme } from "@/hooks/useTheme";
import { Spacing, BorderRadius, Colors } from "@/constants/theme";
import { useSettings } from "@/context/SettingsContext";
import { useSpotifyAuth } from "@/context/SpotifyAuthContext";
import { Song } from "@shared/songs-data";
import { getApiUrl } from "@/lib/query-client";

const { width: SCREEN_WIDTH } = Dimensions.get("window");
const PLAYER_WIDTH = SCREEN_WIDTH - Spacing.lg * 2;
const PLAYER_HEIGHT = (PLAYER_WIDTH * 9) / 16;

const springConfig: WithSpringConfig = {
  damping: 15,
  mass: 0.3,
  stiffness: 150,
  overshootClamping: true,
};

function GameButton({
  onPress,
  title,
  variant = "primary",
  disabled = false,
}: {
  onPress: () => void;
  title: string;
  variant?: "primary" | "secondary";
  disabled?: boolean;
}) {
  const { theme } = useTheme();
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    if (!disabled) {
      scale.value = withSpring(0.98, springConfig);
    }
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, springConfig);
  };

  const isPrimary = variant === "primary";

  return (
    <Animated.View style={animatedStyle}>
      <Pressable
        style={[
          styles.button,
          isPrimary
            ? { backgroundColor: theme.primary }
            : {
                backgroundColor: "transparent",
                borderWidth: 2,
                borderColor: theme.primary,
              },
          disabled && { opacity: 0.5 },
        ]}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onPress={() => {
          if (!disabled) onPress();
        }}
        disabled={disabled}
      >
        <ThemedText
          style={[
            styles.buttonText,
            { color: isPrimary ? Colors.light.buttonText : theme.primary },
          ]}
        >
          {title}
        </ThemedText>
      </Pressable>
    </Animated.View>
  );
}

type SpotifyDevice = {
  id: string;
  name: string;
  type: string;
  is_active: boolean;
};

function SpotifyPlayer({ spotifyUri, artist, title, onSongChange }: { 
  spotifyUri: string | null; 
  artist: string; 
  title: string;
  onSongChange?: () => void;
}) {
  const { theme } = useTheme();
  const { isAuthenticated, getValidAccessToken } = useSpotifyAuth();
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<SpotifyDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showDevices, setShowDevices] = useState(false);
  const [hasAutoPlayed, setHasAutoPlayed] = useState(false);
  const [devicesFetched, setDevicesFetched] = useState(false);
  const previousUri = useRef<string | null>(null);

  const getSpotifyTrackId = (uri: string | null): string | null => {
    if (!uri) return null;
    const match = uri.match(/spotify:track:([a-zA-Z0-9]+)/);
    return match ? match[1] : null;
  };

  const trackId = getSpotifyTrackId(spotifyUri);

  console.log("[SpotifyPlayer] Rendering with:", { 
    isAuthenticated, 
    spotifyUri, 
    trackId, 
    devicesCount: devices.length, 
    error 
  });

  const fetchDevices = async () => {
    console.log("[SpotifyPlayer] fetchDevices called");
    try {
      setError(null);
      const token = await getValidAccessToken();
      console.log("[SpotifyPlayer] Got token:", token ? "yes" : "no");
      if (!token) {
        setError("Please connect Spotify in Settings");
        return;
      }

      const response = await fetch("https://api.spotify.com/v1/me/player/devices", {
        headers: { Authorization: `Bearer ${token}` },
      });

      console.log("[SpotifyPlayer] Devices response status:", response.status);

      if (!response.ok) {
        const errorBody = await response.text();
        console.log("[SpotifyPlayer] Devices error body:", errorBody);
        if (response.status === 401) {
          setError("Session expired. Please reconnect Spotify in Settings");
        } else if (response.status === 403) {
          setError("Missing permissions. Please reconnect Spotify");
        } else {
          setError("Could not connect to Spotify");
        }
        return;
      }

      const data = await response.json();
      console.log("[SpotifyPlayer] Devices found:", data.devices?.length || 0);
      setDevices(data.devices || []);
      setDevicesFetched(true);
      const activeDevice = data.devices?.find((d: SpotifyDevice) => d.is_active);
      if (activeDevice) {
        setSelectedDevice(activeDevice.id);
      } else if (data.devices?.length > 0) {
        setSelectedDevice(data.devices[0].id);
      }
    } catch (err: any) {
      setError("Could not connect to Spotify");
      setDevicesFetched(true);
      console.error("[SpotifyPlayer] Failed to fetch devices:", err);
    }
  };

  useEffect(() => {
    if (isAuthenticated) {
      fetchDevices();
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (spotifyUri && spotifyUri !== previousUri.current) {
      previousUri.current = spotifyUri;
      if (hasAutoPlayed && isAuthenticated && devices.length > 0) {
        handlePlay();
      }
    }
  }, [spotifyUri, hasAutoPlayed, isAuthenticated, devices.length]);

  const handlePlay = async () => {
    if (!spotifyUri) return;

    setIsLoading(true);
    setError(null);

    try {
      const token = await getValidAccessToken();
      if (!token) {
        setError("Please connect Spotify in Settings");
        setIsLoading(false);
        return;
      }

      const url = selectedDevice 
        ? `https://api.spotify.com/v1/me/player/play?device_id=${selectedDevice}`
        : "https://api.spotify.com/v1/me/player/play";

      const response = await fetch(url, {
        method: "PUT",
        headers: { 
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ uris: [spotifyUri] }),
      });

      if (!response.ok) {
        if (response.status === 404) {
          setError("No active device. Open Spotify on a device first");
        } else if (response.status === 401) {
          setError("Session expired. Please reconnect Spotify");
        } else {
          setError("Failed to play track");
        }
      } else {
        setIsPlaying(true);
        setHasAutoPlayed(true);
      }
    } catch (err: any) {
      setError("Failed to play track");
      console.error("Play error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handlePause = async () => {
    setIsLoading(true);

    try {
      const token = await getValidAccessToken();
      if (!token) {
        setIsLoading(false);
        return;
      }

      const url = selectedDevice 
        ? `https://api.spotify.com/v1/me/player/pause?device_id=${selectedDevice}`
        : "https://api.spotify.com/v1/me/player/pause";

      await fetch(url, {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}` },
      });
      setIsPlaying(false);
    } catch (err) {
      console.error("Pause error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const openSpotify = async () => {
    if (trackId) {
      const webUrl = `https://open.spotify.com/track/${trackId}`;
      try {
        await Linking.openURL(webUrl);
      } catch (error) {
        console.error("Failed to open Spotify:", error);
      }
    }
  };

  if (!isAuthenticated) {
    return (
      <View style={[styles.spotifyContainer, { backgroundColor: "#1DB954" }]}>
        <ThemedText style={styles.spotifyTitle}>
          Connect Your Spotify
        </ThemedText>
        <ThemedText style={[styles.spotifySubtext, { color: "#FFFFFF", opacity: 0.8 }]}>
          Go to Settings to connect your Spotify account
        </ThemedText>
      </View>
    );
  }

  if (!trackId) {
    return (
      <View style={[styles.spotifyContainer, { backgroundColor: theme.backgroundDefault }]}>
        <ThemedText style={[styles.spotifyMessage, { color: theme.textSecondary }]}>
          Spotify link not available for this song
        </ThemedText>
        <ThemedText style={[styles.spotifySubtext, { color: theme.textSecondary }]}>
          Switch to YouTube mode in Settings
        </ThemedText>
      </View>
    );
  }

  if (!devicesFetched) {
    return (
      <View style={[styles.spotifyContainer, { backgroundColor: "#1DB954" }]}>
        <ActivityIndicator size="large" color="#FFFFFF" />
        <ThemedText style={styles.spotifyTitle}>
          Connecting to Spotify...
        </ThemedText>
      </View>
    );
  }

  if (error || devices.length === 0) {
    return (
      <View style={[styles.spotifyContainer, { backgroundColor: "#1DB954" }]}>
        <ThemedText style={styles.spotifyTitle}>
          {error || "No active Spotify devices"}
        </ThemedText>
        <ThemedText style={[styles.spotifySubtext, { color: "#FFFFFF", opacity: 0.8 }]}>
          Open Spotify on any device first
        </ThemedText>
        <View style={styles.spotifyButtonRow}>
          <Pressable style={styles.spotifyButton} onPress={fetchDevices}>
            <ThemedText style={styles.spotifyButtonText}>Retry</ThemedText>
          </Pressable>
          <Pressable style={styles.spotifyButton} onPress={openSpotify}>
            <ThemedText style={styles.spotifyButtonText}>Open Spotify</ThemedText>
          </Pressable>
        </View>
      </View>
    );
  }

  const selectedDeviceName = devices.find(d => d.id === selectedDevice)?.name || "Select device";

  return (
    <View style={[styles.spotifyContainer, { backgroundColor: "#1DB954" }]}>
      <View style={styles.spotifyControls}>
        <Pressable 
          style={styles.deviceSelector}
          onPress={() => setShowDevices(!showDevices)}
        >
          <ThemedText style={styles.deviceText} numberOfLines={1}>
            {selectedDeviceName}
          </ThemedText>
          <ThemedText style={{ color: "#FFFFFF", fontSize: 14 }}>
            {showDevices ? "v" : ">"}
          </ThemedText>
        </Pressable>

        {showDevices ? (
          <View style={styles.deviceList}>
            {devices.map((device) => (
              <Pressable
                key={device.id}
                style={[
                  styles.deviceItem,
                  device.id === selectedDevice && styles.deviceItemSelected,
                ]}
                onPress={() => {
                  setSelectedDevice(device.id);
                  setShowDevices(false);
                }}
              >
                <ThemedText 
                  style={[
                    styles.deviceItemText,
                    device.id === selectedDevice && styles.deviceItemTextSelected,
                  ]}
                >
                  {device.name}
                </ThemedText>
              </Pressable>
            ))}
          </View>
        ) : null}
      </View>

      <Pressable
        style={styles.playButton}
        onPress={isPlaying ? handlePause : handlePlay}
        disabled={isLoading}
      >
        {isLoading ? (
          <ActivityIndicator size="small" color="#1DB954" />
        ) : (
          <ThemedText style={{ color: "#1DB954", fontSize: 18, fontWeight: "700" }}>
            {isPlaying ? "Pause" : "Play"}
          </ThemedText>
        )}
      </Pressable>

      <ThemedText style={styles.spotifyNowPlaying}>
        {isPlaying ? "Playing on Spotify" : "Tap to play"}
      </ThemedText>
    </View>
  );
}

export default function GameScreen() {
  const insets = useSafeAreaInsets();
  const headerHeight = useHeaderHeight();
  const { theme, isDark } = useTheme();
  const { playMode, addToHistory, songHistory } = useSettings();
  const playerRef = useRef<YoutubeIframeRef>(null);

  const [currentSong, setCurrentSong] = useState<Song | null>(null);
  const [isRevealed, setIsRevealed] = useState(false);
  const [isAudioOnly, setIsAudioOnly] = useState(false);
  const [isPlayerReady, setIsPlayerReady] = useState(false);
  const [isLoadingSong, setIsLoadingSong] = useState(false);

  const fetchRandomSong = useCallback(async (excludeCurrentId?: number): Promise<Song | null> => {
    try {
      const countUrl = new URL("/api/songs/count", getApiUrl());
      const countResponse = await fetch(countUrl.toString());
      const { count: totalSongs } = await countResponse.json();

      const historyIds = new Set(songHistory.map(s => s.id));
      if (excludeCurrentId !== undefined) {
        historyIds.add(excludeCurrentId);
      }
      const shouldAvoidDuplicates = historyIds.size < totalSongs * 0.7;

      const maxRetries = shouldAvoidDuplicates ? 10 : 1;

      for (let i = 0; i < maxRetries; i++) {
        const url = new URL("/api/songs/random", getApiUrl());
        const response = await fetch(url.toString());
        if (!response.ok) return null;

        const song = await response.json();

        if (!shouldAvoidDuplicates || !historyIds.has(song.id)) {
          return song;
        }
      }

      const url = new URL("/api/songs/random", getApiUrl());
      const response = await fetch(url.toString());
      if (!response.ok) return null;
      return await response.json();
    } catch (error) {
      console.error("Failed to fetch random song:", error);
      return null;
    }
  }, [songHistory]);

  const onPlayerReady = useCallback(() => {
    setIsPlayerReady(true);
  }, []);

  const onPlayerStateChange = useCallback(async (state: string) => {
    if (state === 'ended') {
      setIsLoadingSong(true);
      const newSong = await fetchRandomSong(currentSong?.id);
      if (newSong) {
        setCurrentSong(newSong);
        setIsRevealed(false);
      }
      setIsLoadingSong(false);
    }
  }, [fetchRandomSong, currentSong?.id]);

  const handleNextSong = useCallback(async () => {
    setIsLoadingSong(true);
    const newSong = await fetchRandomSong(currentSong?.id);
    if (newSong) {
      setCurrentSong(newSong);
      setIsRevealed(false);
    }
    setIsLoadingSong(false);
  }, [fetchRandomSong, currentSong?.id]);


  const handleReveal = () => {
    setIsRevealed(true);
  };

  useEffect(() => {
    let isMounted = true;

    const loadInitialSong = async () => {
      if (!currentSong) {
        setIsLoadingSong(true);
        const initialSong = await fetchRandomSong();
        if (isMounted && initialSong) {
          setCurrentSong(initialSong);
        }
        if (isMounted) {
          setIsLoadingSong(false);
        }
      }
    };

    loadInitialSong();

    return () => {
      isMounted = false;
    };
  }, [fetchRandomSong]);

  useEffect(() => {
    if (currentSong?.youtubeId && isPlayerReady && playerRef.current) {
      setTimeout(() => {
        playerRef.current?.seekTo(0, true);
      }, 300);
    }
  }, [currentSong?.youtubeId, isPlayerReady]);

  useEffect(() => {
    if (currentSong) {
      addToHistory({
        id: currentSong.id,
        placement: currentSong.placement,
        artist: currentSong.artist,
        title: currentSong.title,
        year: currentSong.year,
      });
    }
  }, [currentSong, addToHistory]);

  return (
    <ThemedView
      style={[
        styles.container,
        {
          paddingTop: headerHeight + Spacing.xl,
          paddingBottom: insets.bottom + Spacing.xl,
        },
      ]}
    >
      <View style={styles.playerContainer}>
        {playMode === "youtube" ? (
          <View style={styles.youtubeSection}>
            <View style={styles.videoAudioToggle}>
              <Pressable
                style={[
                  styles.toggleOption,
                  {
                    backgroundColor: !isAudioOnly ? theme.primary : "transparent",
                    borderColor: theme.primary,
                  },
                ]}
                onPress={() => setIsAudioOnly(false)}
              >
                <ThemedText
                  style={[
                    styles.toggleLabel,
                    { color: !isAudioOnly ? "#FFFFFF" : theme.primary },
                  ]}
                >
                  Video
                </ThemedText>
              </Pressable>
              <Pressable
                style={[
                  styles.toggleOption,
                  {
                    backgroundColor: isAudioOnly ? theme.primary : "transparent",
                    borderColor: theme.primary,
                  },
                ]}
                onPress={() => setIsAudioOnly(true)}
              >
                <ThemedText
                  style={[
                    styles.toggleLabel,
                    { color: isAudioOnly ? "#FFFFFF" : theme.primary },
                  ]}
                >
                  Audio
                </ThemedText>
              </Pressable>
            </View>
            <View style={[styles.playerWrapper, isAudioOnly && styles.playerHidden]}>
              {Platform.OS === 'web' ? (
                <YouTubePlayerWeb
                  videoId={currentSong?.youtubeId || ''}
                  width={isAudioOnly ? 1 : PLAYER_WIDTH}
                  height={isAudioOnly ? 1 : PLAYER_HEIGHT}
                  play={true}
                  mute={true}
                  onReady={onPlayerReady}
                  onChangeState={onPlayerStateChange}
                />
              ) : currentSong ? (
                <YoutubePlayer
                  key={`yt-${currentSong.youtubeId}`}
                  ref={playerRef}
                  play={true}
                  mute={true}
                  onReady={onPlayerReady}
                  onChangeState={onPlayerStateChange}
                  height={isAudioOnly ? 1 : PLAYER_HEIGHT}
                  width={isAudioOnly ? 1 : PLAYER_WIDTH}
                  videoId={currentSong.youtubeId}
                  initialPlayerParams={{
                    controls: true,
                    modestbranding: true,
                    rel: false,
                    preventFullScreen: true,
                    playerLang: "en",
                    loop: false,
                    mute: true,
                  }}
                  webViewProps={{
                    allowsInlineMediaPlayback: true,
                    mediaPlaybackRequiresUserAction: false,
                  }}
                />
              ) : (
                <View
                  style={[
                    styles.playerPlaceholder,
                    { backgroundColor: theme.backgroundDefault },
                  ]}
                >
                  <ActivityIndicator size="large" color={theme.primary} />
                </View>
              )}
              {!currentSong && Platform.OS === 'web' ? (
                <View style={[styles.playerOverlay, { backgroundColor: theme.backgroundDefault }]}>
                  <ActivityIndicator size="large" color={theme.primary} />
                </View>
              ) : null}
            </View>
            {isAudioOnly ? (
              <View style={[styles.audioOnlyIndicator, { backgroundColor: theme.backgroundDefault }]}>
                <View style={[styles.muteButton, { backgroundColor: theme.primary }]}>
                  <ThemedText style={{ color: "#FFFFFF", fontSize: 24, fontWeight: "700" }}>
                    Audio
                  </ThemedText>
                </View>
                <ThemedText style={[styles.audioOnlyText, { color: theme.textSecondary }]}>
                  Audio playing (muted for autoplay)
                </ThemedText>
              </View>
            ) : null}
          </View>
        ) : playMode === "spotify" && currentSong ? (
          <SpotifyPlayer
            spotifyUri={currentSong.spotifyUri}
            artist={currentSong.artist}
            title={currentSong.title}
            onSongChange={handleNextSong}
          />
        ) : (
          <View
            style={[
              styles.playerPlaceholder,
              { backgroundColor: theme.backgroundDefault },
            ]}
          >
            <ActivityIndicator size="large" color={theme.primary} />
          </View>
        )}
      </View>

      <View
        style={[styles.infoCard, { backgroundColor: theme.backgroundDefault }]}
      >
        {isRevealed && currentSong ? (
          <Animated.View entering={FadeIn.duration(300)} style={styles.revealedInfo}>
            <ThemedText
              style={[styles.placementNumber, { color: theme.primary }]}
            >
              #{currentSong.placement}
            </ThemedText>
            <ThemedText style={styles.artistName}>
              {currentSong.artist}
            </ThemedText>
            <ThemedText style={styles.songTitle}>{currentSong.title}</ThemedText>
            <ThemedText style={[styles.yearText, { color: theme.textSecondary }]}>
              {currentSong.year}
            </ThemedText>
          </Animated.View>
        ) : (
          <View style={styles.hiddenInfo}>
            <ThemedText style={{ fontSize: 48, color: theme.textSecondary }}>?</ThemedText>
            <ThemedText
              style={[styles.guessText, { color: theme.textSecondary }]}
            >
              Can you guess this song?
            </ThemedText>
          </View>
        )}
      </View>

      <View style={styles.buttonsContainer}>
        {!isRevealed && currentSong ? (
          <GameButton
            onPress={handleReveal}
            title="Reveal"
            variant="primary"
            disabled={!currentSong}
          />
        ) : null}
        <GameButton
          onPress={handleNextSong}
          title="Next Song"
          variant={isRevealed ? "primary" : "secondary"}
          disabled={!currentSong}
        />
      </View>
    </ThemedView>
  );
}

