import React, { useState } from "react";
import {
  View,
  StyleSheet,
  ScrollView,
  ActivityIndicator,
  Pressable,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useNavigation } from "@react-navigation/native";

import { ThemedText } from "@/components/ThemedText";
import { ThemedView } from "@/components/ThemedView";
import { useTheme } from "@/hooks/useTheme";
import { useSettings } from "@/context/SettingsContext";
import { Spacing, BorderRadius } from "@/constants/theme";
import { apiRequest } from "@/lib/query-client";

type SongList = {
  folder: string;
  files: string[];
};

export default function SongListScreen() {
  const insets = useSafeAreaInsets();
  const { theme } = useTheme();
  const navigation = useNavigation();
  const queryClient = useQueryClient();
  const { selectedSongList, setSelectedSongList } = useSettings();
  const [expandedFolder, setExpandedFolder] = useState<string | null>(null);

  const { data: songLists, isLoading } = useQuery<SongList[]>({
    queryKey: ["/api/songlists"],
  });

  const importMutation = useMutation({
    mutationFn: async ({ folder, file }: { folder: string; file: string }) => {
      return apiRequest("POST", "/api/songlists/import", { folder, file });
    },
    onSuccess: (_, variables) => {
      setSelectedSongList({ folder: variables.folder, file: variables.file });
      queryClient.invalidateQueries({ queryKey: ["/api/songs"] });
      navigation.goBack();
    },
  });

  const handleSelectList = (folder: string, file: string) => {
    importMutation.mutate({ folder, file });
  };

  const formatFileName = (name: string) => {
    return name.replace(/\.csv$/, "").replace(/[-_]/g, " ");
  };

  const formatFolderName = (name: string) => {
    return name.charAt(0).toUpperCase() + name.slice(1);
  };

  return (
    <ThemedView style={styles.container}>
      <ScrollView
        contentContainerStyle={[
          styles.content,
          { paddingBottom: insets.bottom + Spacing.xl },
        ]}
        showsVerticalScrollIndicator={false}
      >
        {selectedSongList ? (
          <View style={[styles.currentListCard, { backgroundColor: theme.backgroundDefault }]}>
            <View style={styles.currentListHeader}>
              <ThemedText style={styles.currentListLabel}>Currently Selected</ThemedText>
            </View>
            <ThemedText style={[styles.currentListName, { color: theme.primary }]}>
              {formatFolderName(selectedSongList.folder)} - {formatFileName(selectedSongList.file)}
            </ThemedText>
          </View>
        ) : null}

        <ThemedText style={[styles.helpText, { color: theme.textSecondary }]}>
          Select a song list to play from. The selected list will be used for drawing random songs.
        </ThemedText>

        {isLoading ? (
          <View style={styles.loadingContainer}>
            <ActivityIndicator size="large" color={theme.primary} />
          </View>
        ) : (
          <View style={styles.listContainer}>
            {songLists?.map((list) => (
              <View key={list.folder} style={[styles.folderCard, { backgroundColor: theme.backgroundDefault }]}>
                <Pressable
                  style={styles.folderHeader}
                  onPress={() => setExpandedFolder(expandedFolder === list.folder ? null : list.folder)}
                >
                  <View style={styles.folderInfo}>
                    <View style={[styles.folderIcon, { backgroundColor: theme.primary + "20" }]}>
                      <ThemedText style={{ color: theme.primary, fontSize: 14, fontWeight: "600" }}>
                        {formatFolderName(list.folder).charAt(0)}
                      </ThemedText>
                    </View>
                    <View>
                      <ThemedText style={styles.folderName}>{formatFolderName(list.folder)}</ThemedText>
                      <ThemedText style={[styles.fileCount, { color: theme.textSecondary }]}>
                        {list.files.length} {list.files.length === 1 ? "list" : "lists"}
                      </ThemedText>
                    </View>
                  </View>
                  <ThemedText style={{ color: theme.textSecondary, fontSize: 16 }}>
                    {expandedFolder === list.folder ? "v" : ">"}
                  </ThemedText>
                </Pressable>

                {expandedFolder === list.folder ? (
                  <View style={styles.fileList}>
                    {list.files.map((file) => {
                      const isSelected = selectedSongList?.folder === list.folder && selectedSongList?.file === file;
                      const isImporting = importMutation.isPending && 
                        importMutation.variables?.folder === list.folder && 
                        importMutation.variables?.file === file;

                      return (
                        <Pressable
                          key={file}
                          style={[
                            styles.fileRow,
                            {
                              backgroundColor: isSelected ? theme.primary + "15" : theme.backgroundSecondary,
                              borderColor: isSelected ? theme.primary : "transparent",
                            },
                          ]}
                          onPress={() => handleSelectList(list.folder, file)}
                          disabled={importMutation.isPending}
                        >
                          <View style={styles.fileInfo}>
                            {isImporting ? (
                              <ActivityIndicator size="small" color={theme.primary} />
                            ) : null}
                            <ThemedText
                              style={[
                                styles.fileName,
                                { color: isSelected ? theme.primary : theme.text },
                              ]}
                            >
                              {formatFileName(file)}
                            </ThemedText>
                          </View>
                          {isSelected ? (
                            <View style={[styles.selectedBadge, { backgroundColor: theme.primary }]}>
                              <ThemedText style={styles.selectedBadgeText}>Active</ThemedText>
                            </View>
                          ) : null}
                        </Pressable>
                      );
                    })}
                  </View>
                ) : null}
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </ThemedView>
  );
}

