export type Song = {
  id: number;
  placement: number;
  artist: string;
  title: string;
  year: number;
  youtubeId: string;
  spotifyUri: string | null;
};

let currentSongs: Song[] = [];

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  result.push(current.trim());

  return result;
}

export function loadSongsFromCSV(csvContent: string): number {
  const lines = csvContent.split("\n").filter(line => line.trim());

  if (lines.length < 2) {
    return 0;
  }

  const header = parseCSVLine(lines[0]);
  const placementIdx = header.findIndex(h => h.toLowerCase() === "notering");
  const titleIdx = header.findIndex(h => h.toLowerCase().includes("track name"));
  const artistIdx = header.findIndex(h => h.toLowerCase().includes("artist"));
  const yearIdx = header.findIndex(h => h.toLowerCase() === "jaartal");
  const youtubeIdx = header.findIndex(h => h.toLowerCase().includes("youtube"));
  const spotifyIdx = header.findIndex(h => h.toLowerCase().includes("track uri") || h.toLowerCase().includes("spotify"));

  const newSongs: Song[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);

    const placement = parseInt(values[placementIdx], 10);
    const title = values[titleIdx] || "";
    const artist = values[artistIdx] || "";
    const year = parseInt(values[yearIdx], 10);
    const youtubeId = values[youtubeIdx] || "";
    const spotifyUri = values[spotifyIdx] || null;

    if (!isNaN(placement) && title && artist && !isNaN(year)) {
      newSongs.push({
        id: i,
        placement,
        artist,
        title,
        year,
        youtubeId,
        spotifyUri,
      });
    }
  }

  if (newSongs.length > 0) {
    currentSongs = newSongs;
  }

  return newSongs.length;
}

export function getRandomSong(): Song | null {
  if (currentSongs.length === 0) {
    return null;
  }
  return currentSongs[Math.floor(Math.random() * currentSongs.length)];
}

export function getSongById(id: number): Song | undefined {
  return currentSongs.find(song => song.id === id);
}

export function getAllSongs(): Song[] {
  return currentSongs;
}

export function getSongCount(): number {
  return currentSongs.length;
}

export function setSongs(songs: Song[]): void {
  currentSongs = songs;
}

