import type { Song } from "../songs-data";

import { songs as top2000_top2025_songs, metadata as top2000_top2025_meta } from "./top2000_top2025";
import { songs as hits_Nederland_top_50_2025_songs, metadata as hits_Nederland_top_50_2025_meta } from "./hits_Nederland_top_50_2025";
import { songs as hits_Wereld_top_50_2025_songs, metadata as hits_Wereld_top_50_2025_meta } from "./hits_Wereld_top_50_2025";

export type EmbeddedSongList = {
  folder: string;
  file: string;
  songs: Song[];
};

export const embeddedSongLists: Record<string, EmbeddedSongList> = {
  "top2000/top2025.csv": { folder: "top2000", file: "top2025.csv", songs: top2000_top2025_songs },
  "hits/Nederland_top_50-2025.csv": { folder: "hits", file: "Nederland_top_50-2025.csv", songs: hits_Nederland_top_50_2025_songs },
  "hits/Wereld_top_50-2025.csv": { folder: "hits", file: "Wereld_top_50-2025.csv", songs: hits_Wereld_top_50_2025_songs },
};

export const songListManifest: { folder: string; files: string[] }[] = [
  { folder: "top2000", files: ["top2025.csv"] },
  { folder: "hits", files: ["Nederland_top_50-2025.csv","Wereld_top_50-2025.csv"] },
];

export function getEmbeddedSongs(folder: string, file: string): Song[] {
  const key = `${folder}/${file}`;
  return embeddedSongLists[key]?.songs || [];
}

export function getDefaultSongs(): Song[] {
  return getEmbeddedSongs("top2000", "top2025.csv");
}

scripts/embed-songs.ts.content:
import * as fs from "fs";
import * as path from "path";

const SONG_CSV_DIR = path.join(process.cwd(), "server", "songcsv");
const OUTPUT_DIR = path.join(process.cwd(), "shared", "embedded-songs");
const MANIFEST_PATH = path.join(SONG_CSV_DIR, "manifest.json");

type SongListManifest = {
  songLists: { folder: string; files: string[] }[];
};

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  result.push(current.trim());

  return result;
}

function escapeString(str: string): string {
  return str.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");
}

function convertCSVToSongs(csvContent: string): any[] {
  const lines = csvContent.split("\n").filter(line => line.trim());

  if (lines.length < 2) {
    return [];
  }

  const header = parseCSVLine(lines[0]);
  const placementIdx = header.findIndex(h => h.toLowerCase() === "notering");
  const titleIdx = header.findIndex(h => h.toLowerCase().includes("track name"));
  const artistIdx = header.findIndex(h => h.toLowerCase().includes("artist"));
  const yearIdx = header.findIndex(h => h.toLowerCase() === "jaartal");
  const youtubeIdx = header.findIndex(h => h.toLowerCase().includes("youtube"));
  const spotifyIdx = header.findIndex(h => h.toLowerCase().includes("track uri") || h.toLowerCase().includes("spotify"));

  const songs: any[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);

    const placement = parseInt(values[placementIdx], 10);
    const title = values[titleIdx] || "";
    const artist = values[artistIdx] || "";
    const year = parseInt(values[yearIdx], 10);
    const youtubeId = values[youtubeIdx] || "";
    const spotifyUri = values[spotifyIdx] || null;

    if (!isNaN(placement) && title && artist && !isNaN(year)) {
      songs.push({
        id: i,
        placement,
        artist,
        title,
        year,
        youtubeId,
        spotifyUri,
      });
    }
  }

  return songs;
}

function sanitizeFileName(name: string): string {
  return name.replace(/[^a-zA-Z0-9]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "");
}

function main() {
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  const manifest: SongListManifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf-8"));
  const embeddedManifest: { folder: string; file: string; moduleName: string }[] = [];

  for (const songList of manifest.songLists) {
    for (const file of songList.files) {
      const csvPath = path.join(SONG_CSV_DIR, songList.folder, file);

      if (!fs.existsSync(csvPath)) {
        console.warn(`CSV not found: ${csvPath}`);
        continue;
      }

      const csvContent = fs.readFileSync(csvPath, "utf-8");
      const songs = convertCSVToSongs(csvContent);

      const moduleName = `${sanitizeFileName(songList.folder)}_${sanitizeFileName(file.replace(".csv", ""))}`;
      const outputPath = path.join(OUTPUT_DIR, `${moduleName}.ts`);

      const tsContent = `import type { Song } from "../songs-data";

export const songs: Song[] = ${JSON.stringify(songs, null, 2)};

export const metadata = {
  folder: "${songList.folder}",
  file: "${file}",
  count: ${songs.length},
};
`;

      fs.writeFileSync(outputPath, tsContent);
      console.log(`Generated: ${moduleName}.ts (${songs.length} songs)`);

      embeddedManifest.push({
        folder: songList.folder,
        file: file,
        moduleName: moduleName,
      });
    }
  }

  const indexContent = `import type { Song } from "../songs-data";

${embeddedManifest.map(m => `import { songs as ${m.moduleName}_songs, metadata as ${m.moduleName}_meta } from "./${m.moduleName}";`).join("\n")}

export type EmbeddedSongList = {
  folder: string;
  file: string;
  songs: Song[];
};

export const embeddedSongLists: Record<string, EmbeddedSongList> = {
${embeddedManifest.map(m => `  "${m.folder}/${m.file}": { folder: "${m.folder}", file: "${m.file}", songs: ${m.moduleName}_songs },`).join("\n")}
};

export const songListManifest: { folder: string; files: string[] }[] = [
${manifest.songLists.map(sl => `  { folder: "${sl.folder}", files: ${JSON.stringify(sl.files)} },`).join("\n")}
];

export function getEmbeddedSongs(folder: string, file: string): Song[] {
  const key = \`\${folder}/\${file}\`;
  return embeddedSongLists[key]?.songs || [];
}

export function getDefaultSongs(): Song[] {
  return getEmbeddedSongs("top2000", "top2025.csv");
}
`;

  fs.writeFileSync(path.join(OUTPUT_DIR, "index.ts"), indexContent);
  console.log("Generated: index.ts");
  console.log(`\nTotal: ${embeddedManifest.length} song lists embedded`);
}

main();
